from lib import *
S = SS('s36')
steps = [
    step("CLOSESPIDER_PAGECOUNT 到数后关闭,但不是“精确停”:站点 200 页、并发 16、每页 0.05 s。PAGECOUNT = 10 实际收到 24 个响应(服务器收到 24 个请求含起始页),PAGECOUNT = 50 收到 65 个;不限制则 201 个。多出来的是触发时已经发出去的请求(并发 16 个在途)加上关闭本身是异步的;scheduler/enqueued 仍是 201,没发出去的都留在调度器里被丢弃(dequeued 只有 24 / 65)。finish_reason = closespider_pagecount。", t=tl(S(1)), mark=lidx(S(1), 'PAGECOUNT=10', 'PAGECOUNT=50'), done=lidx(S(1), '不限制'), b=bars([['PAGECOUNT=10', 24, '24 个响应'], ['PAGECOUNT=50', 65, '65 个响应'], ['不限制', 201, '201 个响应']], 201, mark=[0, 1], done=[2]), kv=KV([['PAGECOUNT = 10', '实际 24 个响应'], ['PAGECOUNT = 50', '实际 65 个响应'], ['多出来的', '关闭时已在途的请求 + 异步关闭'], ['调度器里的', '全部丢弃(dequeued 只有 24 / 65)']], ['多出来的'])),
    step("CLOSESPIDER_ITEMCOUNT 同样会超:每页 1 个 item,ITEMCOUNT = 10 时 item_scraped_count = 32(服务器收到 33 个请求),= 50 时 71 个(72 个请求)。因为 item 在响应之后才被抓出来,关闭时在途的请求更多,比 PAGECOUNT 多得更厉害。", t=tl(S(2)), mark=lidx(S(2), 'ITEMCOUNT=10', 'ITEMCOUNT=50'), kv=KV([['ITEMCOUNT = 10', 'item_scraped_count = 32'], ['ITEMCOUNT = 50', 'item_scraped_count = 71'], ['原因', 'item 比响应更晚计数,关闭时在途的更多']], ['ITEMCOUNT = 10'])),
    step("CLOSESPIDER_ERRORCOUNT 只数 spider_error 信号(回调里抛的异常):回调对每页抛 ValueError,ERRORCOUNT = 5 关闭时 spider_exceptions/count = 32(也超出了 5),finish_reason = closespider_errorcount;服务器对每页返回 404 时 404 不算 spider_error,ERRORCOUNT = 5 完全没触发,61 个请求全部抓完,finish_reason = finished。", t=tl(S(3)), mark=lidx(S(3), '404', '回调抛异常'), kv=KV([['回调抛异常', '计入,触发 ERRORCOUNT'], ['404 / 下载失败', '不计入'], ['超出', '关闭时已在途的回调还会继续抛']], ['404 / 下载失败'])),
    step("时间类:CLOSESPIDER_TIMEOUT = 1(并发 2、每页 0.1 s)到 1 秒关闭,耗时 1.01 s,收到 19 个响应;CLOSESPIDER_TIMEOUT_NO_ITEM = 2 在页面不产出 item 时每隔 2 秒检查一次,耗时 2.10 s 以 closespider_timeout_no_item 结束(39 个响应);CLOSESPIDER_PAGECOUNT_NO_ITEM = 20 在连续 20 个页面没有 item 时关闭,只有 p0~p2 产出 item 的站点(并发 1)抓了 20 个响应就关了,耗时 0.03 s,finish_reason = closespider_pagecount_no_item。", t=tl(S(4)), mark=lidx(S(4), 'TIMEOUT=1 s', 'TIMEOUT_NO_ITEM=2 s', 'PAGECOUNT_NO_ITEM=20'), kv=KV([['TIMEOUT', '从 spider 打开起算,到时关闭'], ['TIMEOUT_NO_ITEM', '一个周期内没有 item 就关'], ['PAGECOUNT_NO_ITEM', '连续这么多页没有 item 就关']], ['TIMEOUT'])),
    step("MemoryUsage 扩展读的是进程的峰值 RSS(ru_maxrss,只增不减),默认每 60 秒才更新一次:不设限时 40 个页面各分配并保留 10 MiB,memusage/startup 和 max 却都是 86 MiB(没到下一次更新);把 MEMUSAGE_CHECK_INTERVAL_SECONDS 调成 0.2 后 max = 469 MiB。MEMUSAGE_WARNING_MB = 110 超过时只记 WARNING “Memory usage reached 110MiB”、设 memusage/warning_reached = 1、发信号,爬虫照常跑完 40 个 item;MEMUSAGE_LIMIT_MB = 130 超过时 ERROR “Memory usage exceeded 130MiB. Shutting down Scrapy...”,memusage/limit_reached = 1,finish_reason = memusage_exceeded,只抓了 7 个 item,max 148 MiB(检查间隔里已经超过了限制)。", t=tl(S(5)), mark=lidx(S(5), 'MEMUSAGE_LIMIT_MB=130', 'MEMUSAGE_WARNING_MB=110'), done=lidx(S(5), '不设限'), b=bars([['不设限(60 s 才检查)', 86, 'max 86 MiB'], ['限制 130 的运行', 148, 'max 148 MiB'], ['警告 110 的运行', 469, 'max 469 MiB']], 469, mark=[1], done=[0, 2]), kv=KV([['读数', '峰值 RSS(ru_maxrss),只增不减'], ['检查周期', '默认 60 秒'], ['WARNING_MB', '只告警 + 信号'], ['LIMIT_MB', '超过就 memusage_exceeded 关闭']], ['检查周期'])),
]
A = mkarts('s36', 36, 'Scrapy,CloseSpider,MemoryUsage,CLOSESPIDER_PAGECOUNT,MEMUSAGE_LIMIT_MB,真实验证,动画演示',
    '实测 CloseSpider 与 MemoryUsage:PAGECOUNT = 10 实际收到 24 个响应、ITEMCOUNT = 10 实际 32 个 item(都因在途请求而超出);ERRORCOUNT 只数回调异常、不数 404;TIMEOUT、TIMEOUT_NO_ITEM、PAGECOUNT_NO_ITEM 的关闭原因;内存读数是峰值 RSS 且默认 60 秒才更新一次,超过 MEMUSAGE_LIMIT_MB 以 memusage_exceeded 关闭。',
    '想让爬虫到点自己停下来,有 CLOSESPIDER_* 一组设置和 MemoryUsage 扩展。它们精确吗?超出多少?哪些错误算数?内存限制是怎么量的?这篇用能计数的服务器和故意吃内存的回调逐项实测。',
    [('24 vs 10', 'CLOSESPIDER_PAGECOUNT = 10 实际收到的响应数(并发 16)'), ('60 s', 'MemoryUsage 默认检查周期(不调小的话短爬虫里 max 永远等于 startup)'), ('memusage_exceeded', '内存超过 MEMUSAGE_LIMIT_MB 时的 finish_reason')],
    [('PAGECOUNT', '<p><code>CLOSESPIDER_PAGECOUNT</code> 到数就异步关闭爬虫,关闭那一刻在途的请求还会完成,所以实际响应数比设置值大;调度器里排队的请求被丢弃。</p>'),
     ('ITEMCOUNT', '<p><code>CLOSESPIDER_ITEMCOUNT</code> 同理;item 比响应更晚计数,超出得更多。</p>'),
     ('错误计数', '<p><code>CLOSESPIDER_ERRORCOUNT</code> 只数 <code>spider_error</code> 信号(回调里的异常),HTTP 404、下载失败不算。</p>'),
     ('时间类', '<p><code>CLOSESPIDER_TIMEOUT</code> 从 spider 打开开始计时;<code>TIMEOUT_NO_ITEM</code> 每隔一个周期检查是否有新 item;<code>PAGECOUNT_NO_ITEM</code> 数连续没有 item 的页面。</p>'),
     ('MemoryUsage', '<p>读 <code>ru_maxrss</code>(进程峰值 RSS),每 <code>MEMUSAGE_CHECK_INTERVAL_SECONDS</code>(默认 60)检查一次;超过 <code>MEMUSAGE_LIMIT_MB</code> 关闭爬虫,超过 <code>MEMUSAGE_WARNING_MB</code> 只告警并发信号。</p>')],
    steps,
    [ENV_Y + '。站点 200 个页面(服务器端 time.sleep 制造延迟),并发 16 或更小;内存实验里回调每次分配 10 MiB 并保留;检查间隔调成 0.2 s 才能看到超限',
     '没有验证:Linux 上 ru_maxrss 的单位(源码按平台换算,macOS 上是字节);MEMUSAGE_NOTIFY_MAIL(源码标注弃用并发警告);关闭后 pipeline 里排队的 item 是否处理完(item_scraped_count 与 CLOSESPIDER_ITEMCOUNT 的差距提示会处理);CLOSESPIDER_TIMEOUT 与 DontCloseSpider 的组合;多个 crawler 在同一进程里 MemoryUsage 读到的是整个进程的内存'],
    '自动停止')
